package domain

import (
	"github.com/google/uuid"
)

// TraceID represents a unique identifier for tracing requests across the system.
// It is a Value Object: immutable after creation, validated in the constructor.
// TraceID must always come from the client via the HTTP X-Trace-ID header,
// passed through the Kafka event. It is NOT generated by the system.
type TraceID string

// NewTraceID creates and validates a new TraceID from a client-provided header value.
// The value MUST be provided - it comes from the HTTP X-Trace-ID header.
// Returns error if the provided value is not a valid UUID v4.
func NewTraceID(headerValue *string) (TraceID, error) {
	// TraceID is required - must come from client
	if headerValue == nil || *headerValue == "" {
		return "", NewAppError(
			"MISSING_TRACE_ID",
			"trace_id is required and must be provided by the client",
			nil,
		)
	}

	// Attempt to parse as UUID v4
	parsed, err := uuid.Parse(*headerValue)
	if err != nil {
		return "", NewAppError(
			"INVALID_TRACE_ID",
			"trace_id is not a valid UUID v4",
			err,
		)
	}

	// Verify that the parsed UUID is actually v4
	if parsed.Version() != 4 {
		return "", NewAppError(
			"INVALID_TRACE_ID",
			"trace_id must be a UUID v4",
			nil,
		)
	}

	return TraceID(parsed.String()), nil
}

// String returns the TraceID as a string.
func (t TraceID) String() string {
	return string(t)
}
